const areas=[['Career exploration','Make sense of possible paths and choose a direction that fits your strengths.','Which path fits?','/images/guidance-career-exploration.png'],['Higher studies','Think through programmes, applications, research, and the next academic step.','Programmes & applications','/images/guidance-higher-studies.png'],['Interview preparation','Practise the thinking and storytelling that help you show up prepared.','Tell my story','/images/guidance-interview.png'],['Skill development','Build a practical next step with someone who has done it before.','What to build next','/images/guidance-skills.png'],['Employment and job search','Make the first move with relevant context and a person in the loop.','Finding first roles','/images/guidance-job-search.png']]
